 *                               "bice"). Auto-derived from configPath basename when not set
 *                               (e.g. ".dmtools/configs/myproject.js" → "myproject").
 *   skipIfLabel    (optional) — skip ticket if it already has this label (idempotency)
 *   skipIfLabels   (optional) — skip ticket if it already has any of these labels
 *   addLabel       (optional) — add this label after triggering (idempotency marker)
 *   addLabels      (optional) — add these labels after triggering
 *   recoverStaleTriggerLabel (optional) — if true, remove skip labels when no matching
 *                               active workflow exists and continue processing. Trigger
 *                               labels that are also added by the same rule recover by
 *                               default; set false to opt out.
 *   enabled        (optional) — set to false to disable the rule entirely (default: true)
 *   limit          (optional) — max number of tickets to process per run (default: 50)
 *   localExecution (optional) — if true, run postJSAction directly (no runner, no AI/CLI)
 *   localTeammate  (optional) — if true, run the full teammate pipeline (checkout, AI CLI,
 *                               PR/Jira actions) synchronously in-process via
 *                               scripts/run-teammate-local.sh instead of dispatching a
 *                               GitHub Actions workflow_dispatch. Tickets are processed
 *                               strictly one at a time (the local checkout is reused across
 *                               tickets, so no concurrency/workflowBudget accounting applies).
 *                               Secrets are read from the calling shell's environment or from
 *                               dmtools.env (see scripts/run-agent.sh loader) — never from
 *                               GitHub Actions secrets.
 *   localTeammateScript (optional) — path to the local runner script
 *                               (default: agents/scripts/run-teammate-local.sh)
 */

// Dry-run mode: log every side effect instead of performing it (dispatches,
// label moves, status moves, local executions). Set from jobParams.dryRun.
var DRY = false;

var configLoader = require('./configLoader.js');
var smSource = require('./sm/sourceResolver.js');
var scmModule = require('./common/scm.js');
var factoryStateModule = require('./factoryState.js');
var reworkLatchModule = require('./common/reworkLatch.js');
// gh-821: the arm-must-mean-a-live-run state machine — liveness
// classification of the head's dispatched-run probe + the zombie
// re-dispatch marker math (crash-loop cap, 1/head/hour bound).
var validationLivenessModule = require('./common/validationLiveness.js');
// gh-842: the gate-ghost classifier — pending check-runs whose backing
// run is gone/cancelled/stale (check-RUN zombies); the run-level gh-821
// twin cannot see them while a green run still exists on the head.
var checkRunZombiesModule = require('./common/checkRunZombies.js');
var buildEncodedConfigModule = require('./common/buildEncodedConfig.js');
var machineAuthorModule = require('./common/machineAuthor.js');
var smProviderModule = require('./common/smProvider.js');
var trackersModule = require('./common/trackers.js');
// gh-916 review: the DEFAULT status names (config.js STATUSES) back the second pass of
// stageKeyForStatusName — a project that renames a status still keeps the sm.json literal
// targetStatus, and the stage-key resolution must not silently lose the fallback there.
var configModule = require('./config.js');
// gh-807: machine review-verdict records + their reconciliation logic.
var reviewVerdictsModule = require('./common/reviewVerdicts.js');
var redConvergenceModule = require('./common/redConvergence.js');
// gh-840 (hoisted, never lazy — the gh-823 pack-require rule): fail-closed
// agent:rework consumption bookkeeping — the consume-audit markers the
// processRule consumeLabels paths stamp, and the pure consumed-without-work
// sweep decision the restore_rework_arm localAction consults.
var reworkConsumptionModule = require('./common/reworkConsumption.js');
// gh-957 (hoisted, never lazy — the gh-823 pack-require rule): the rework
// no-op loop guard — lap-marker build/parse, the consecutive-no-op-lap count
// (pushed 0 AND resolved 0 on one head) and the once-per-head escalation
// marker math. The threads-armed arm_rework path had NO bound (live dart
// #424: 7 no-op legs / 2h starved the whole queue).
var reworkLoopGuardModule = require('./common/reworkLoopGuard.js');
// gh-922 (hoisted, never lazy — the gh-823 pack-require rule): fail-open
// dispatch vocabulary — the no-ref/transient error classification, the
// ⚠️ trigger-failed marker math and the dead-head park cap. The pure
// half lives in the module; recordDispatchFailure below wires transport.
var triggerFailuresModule = require('./common/triggerFailures.js');
